import React, { useState } from "react";

const JobCard = ({ job, currentUser }) => {
  const [likes, setLikes] = useState(job.likes);
  const [showPopup, setShowPopup] = useState(false);
  const [isLiked, setIsLiked] = useState(false);
  const [applyMessage, setApplyMessage] = useState("");
  const [counterOffer, setCounterOffer] = useState("");

  const jobURL = window.location.href; // Replace with actual job URL

  const handleShareClick = () => {
    setShowPopup(!showPopup);
  };

  const handleCopyLink = () => {
    navigator.clipboard.writeText(jobURL);
    alert("Link copied to clipboard!");
  };

  const handleLike = async () => {
    if (isLiked) return alert("You already liked this job!");

    try {
      const response = await fetch(`/api/jobs/${job._id}/like`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${localStorage.getItem("token")}`, // Assuming token is stored in localStorage
        },
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || "Error liking job.");
      }

      setLikes((prevLikes) => prevLikes + 1);
      setIsLiked(true);
    } catch (error) {
      alert(error.message);
    }
  };

  const handleApplySubmit = async () => {
    if (!applyMessage.trim()) {
      return alert("Message cannot be empty.");
    }

    try {
      const response = await fetch("/api/messages/send", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${localStorage.getItem("token")}`, // Auth required
        },
        body: JSON.stringify({
          senderId: currentUser._id, // Current user (applicant)
          receiverId: job.postedBy, // Job poster (client)
          jobId: job._id, // Job ID
          message: applyMessage,
          counterOffer: counterOffer || job.budget, // Default to job budget if empty
        }),
      });

      if (!response.ok) {
        throw new Error("Failed to send message.");
      }

      alert("Application sent successfully!");
      setShowPopup(false);
      setApplyMessage("");
      setCounterOffer("");
    } catch (error) {
      alert(error.message);
    }
  };

  return (
    <div className="job-card">
      {/* Job Image */}
      {job.fileAttachment && (
        <img src={job.fileAttachment} alt={job.title} className="job-image" />
      )}

      <div className="job-content">
        <h3>{job.title}</h3>
        <p>{job.description}</p>

        <div className="skills-tags">
          {job.skillsRequired.map((skill, index) => (
            <span key={index}>{skill}</span>
          ))}
        </div>

        <div className="job-meta">
          <span>💰 ${job.budget}</span>
          <span>⏳ {job.timeline}</span>
          <span>❤️ {likes} Likes</span>
        </div>

        <div className="engagement-buttons">
          <button className="like-btn" onClick={handleLike}>
            {isLiked ? "✅ Liked" : "❤️ Like"}
          </button>
          <button className="bookmark-btn">📌</button>
          <button className="share-btn" onClick={handleShareClick}>📤 Share</button>
        </div>

        <button className="apply-btn" onClick={() => setShowPopup(true)}>Apply Now</button>
      </div>

      {/* Apply Popup */}
      {showPopup && (
        <div className="apply-popup">
          <h3>Apply for {job.title}</h3>
          <textarea
            placeholder="Write your message..."
            value={applyMessage}
            onChange={(e) => setApplyMessage(e.target.value)}
          />
          <input
            type="number"
            placeholder="Counter Offer (Optional)"
            value={counterOffer}
            onChange={(e) => setCounterOffer(e.target.value)}
          />
          <button onClick={handleApplySubmit}>Submit</button>
          <button onClick={() => setShowPopup(false)}>Cancel</button>
        </div>
      )}
    </div>
  );
};

export default JobCard;
